import React, { useEffect, useState, useCallback } from "react";
import "../static/css/pageAlerts.css";
import { useParams } from "react-router-dom";

const PageAlerts = () => {
    const { id } = useParams();
    const [alerts, setAlerts] = useState([]);
    const [cryptos, setCryptos] = useState([]);
    const [userData, setUserData] = useState({});
    const [showPopup, setShowPopup] = useState({ create: false, update: false, delete: false });
    const [currentAlert, setCurrentAlert] = useState(null);

    const [newAlert, setNewAlert] = useState({
        name: "",
        crypto_id: "",
        priceThreshold: "",
        variationThreshold: "",
    });

    const credentials = btoa("momo:Avignon2024@?");

    const fetchData = useCallback(async (url, method = "GET", body = null) => {
        try {
            const response = await fetch(url, {
                method,
                headers: {
                    Authorization: `Basic ${credentials}`,
                    "Content-Type": "application/json",
                },
                body: body ? JSON.stringify(body) : null,
            });
            if (!response.ok) throw new Error(await response.text());
            return await response.json();
        } catch (error) {
            console.error(`Erreur lors de la requête vers ${url} :`, error);
            alert("Une erreur est survenue. Veuillez réessayer.");
        }
    }, [credentials]);

    useEffect(() => {
        const loadData = async () => {
            const user = await fetchData(`/api/users/${id}`);
            if (user) setUserData(user);

            const userAlerts = await fetchData(`/api/alerts/${id}`);
            setAlerts(userAlerts || []);

            const cryptoList = await fetchData("/api/cryptocurrencies");
            setCryptos(cryptoList || []);
        };
        loadData();
    }, [id, fetchData]);

    const handleCreateAlert = async () => {
        if (alerts.length >= 10) {
            alert("Vous avez atteint la limite de 10 alertes. Passez à un abonnement premium pour ajouter plus d'alertes.");
            return;
        }

        if (!newAlert.crypto_id || !newAlert.priceThreshold || !newAlert.variationThreshold) {
            alert("Veuillez remplir tous les champs obligatoires.");
            return;
        }

        const cryptoCurrency = await fetchData(`/api/cryptocurrencies/${newAlert.crypto_id}`);
        if (!cryptoCurrency) return;

        const payload = { ...newAlert, user: userData, cryptoCurrency };
        const createdAlert = await fetchData("/api/alerts/create", "POST", payload);
        if (createdAlert) {
            setAlerts((prevAlerts) => [...prevAlerts, createdAlert]);
            setShowPopup({ ...showPopup, create: false });
        }
    };

    const handleUpdateAlert = async () => {
        const updatedAlert = await fetchData(`/api/alerts/update/${currentAlert.id}`, "PUT", currentAlert);
        if (updatedAlert) {
            setAlerts((prevAlerts) =>
                prevAlerts.map((alert) => (alert.id === updatedAlert.id ? updatedAlert : alert))
            );
            setShowPopup({ ...showPopup, update: false });
        }
    };

    const handleDeleteAlert = async () => {
        const success = await fetchData(`/api/alerts/delete/${currentAlert.id}`, "DELETE");
        if (success) {
            setAlerts((prevAlerts) => prevAlerts.filter((alert) => alert.id !== currentAlert.id));
            setShowPopup({ ...showPopup, delete: false });
        }
    };

    return (
        <div className="app">
            <header className="app-header">
                <h1>La Cryptomonnaie de l'avenir</h1>
                <button onClick={() => (window.location.href = `/Dashboard/${userData.id}`)}>Retour à ton compte</button>
                <button onClick={() => (window.location.href = "/Login")}>Déconnexion</button>
            </header>

            <div className="container">
                <button onClick={() => setShowPopup({ ...showPopup, create: true })}>Créer une alerte</button>
                <h2>Vos alertes</h2>
                <ul>
                    {alerts.map((alert) => (
                        <li key={alert.id}>
                            <div>
                                <h3>{alert.name}</h3>
                                <p>Crypto : {alert.crypto_id}</p>
                                <p>Prix seuil : ${alert.priceThreshold}</p>
                                <p>Variation : {alert.variationThreshold}%</p>
                            </div>
                            <button onClick={() => { setCurrentAlert(alert); setShowPopup({ ...showPopup, update: true }); }}>Modifier</button>
                            <button onClick={() => { setCurrentAlert(alert); setShowPopup({ ...showPopup, delete: true }); }}>Supprimer</button>
                        </li>
                    ))}
                </ul>
            </div>

            {showPopup.create && (
                <Popup
                    title="Créer une nouvelle alerte"
                    alert={newAlert}
                    setAlert={setNewAlert}
                    cryptos={cryptos}
                    onSave={handleCreateAlert}
                    onCancel={() => setShowPopup({ ...showPopup, create: false })}
                />
            )}

            {showPopup.update && (
                <Popup
                    title="Modifier une alerte"
                    alert={currentAlert}
                    setAlert={setCurrentAlert}
                    cryptos={cryptos}
                    onSave={handleUpdateAlert}
                    onCancel={() => setShowPopup({ ...showPopup, update: false })}
                />
            )}

            {showPopup.delete && (
                <div className="popup">
                    <div className="popup-content">
                        <h2>Confirmer la suppression</h2>
                        <p>Êtes-vous sûr de vouloir supprimer cette alerte ?</p>
                        <button onClick={handleDeleteAlert}>Oui</button>
                        <button onClick={() => setShowPopup({ ...showPopup, delete: false })}>Non</button>
                    </div>
                </div>
            )}
        </div>
    );
};

const Popup = ({ title, alert, setAlert, cryptos, onSave, onCancel }) => (
    <div className="popup">
        <div className="popup-content">
            <h2>{title}</h2>
            <label>
                Nom :
                <input type="text" value={alert.name} onChange={(e) => setAlert({ ...alert, name: e.target.value })} />
            </label>
            <label>
                Crypto :
                <select
                    value={alert.crypto_id}
                    onChange={(e) => setAlert({ ...alert, crypto_id: e.target.value })}
                >
                    <option value="">--Choisir--</option>
                    {cryptos.map((crypto) => (
                        <option key={crypto.id} value={crypto.id}>
                            {crypto.name}
                        </option>
                    ))}
                </select>
            </label>
            <label>
                Prix seuil :
                <input
                    type="number"
                    value={alert.priceThreshold}
                    onChange={(e) => setAlert({ ...alert, priceThreshold: e.target.value })}
                />
            </label>
            <label>
                Variation :
                <input
                    type="number"
                    value={alert.variationThreshold}
                    onChange={(e) => setAlert({ ...alert, variationThreshold: e.target.value })}
                />
            </label>
            <button onClick={onSave}>Enregistrer</button>
            <button onClick={onCancel}>Annuler</button>
        </div>
    </div>
);

export default PageAlerts;
